diffs  = {(l, v): st.differential_features(traces[(l, v)], k=K_DIFF)
          for l in ("sae","jlens") for v in ("trained","control")}

# Pour chaque lentille (trained) : quel jeu active le plus, en masse, sur ses features differentielles
for lens in ("sae", "jlens"):
    feat = diffs[(lens, "trained")]
    print(f"--- {lens.upper()} trained : {K_DIFF} features differentielles (top variance inter-jeux) ---")
    for s in SETS:
        profile = means[(lens, "trained")][s][feat]
        print(f"  {s:14s} mean(diff)={profile.mean():+.4f}  max={profile.max():+.3f}  "
              f"nonzero={int((profile != 0).sum())}/{K_DIFF}")
    print()

def concentration_series(traces_dict, lens, variant, metric="gini"):
    """Pour chaque position, un scalaire de concentration sur son top-50."""
    pieces = []
    for s in SETS:
        for i in range(4):
            v = traces_dict[(lens, variant)]["prompts"][(s, i)]["vals"].astype(np.float64)  # [T, 50]
            T = v.shape[0]
            if metric == "gini":
                vs = np.sort(v, axis=1)                       # [T,50] ascendant
                idx = np.arange(1, v.shape[1] + 1)
                num = 2.0 * (vs * idx).sum(axis=1) - (v.shape[1] + 1) * vs.sum(axis=1)
                den = v.shape[1] * vs.sum(axis=1)
                g = np.where(den > 0, num / den, 0.0)
                pieces.append(g)
            elif metric == "top1_share":
                # part de l'activation dans la direction dominante (top-1 / somme)
                pieces.append(v.max(axis=1) / (v.sum(axis=1) + 1e-9))
    return np.concatenate(pieces)

conc = {(l, v): concentration_series(traces, l, v, "gini")
        for l in ("sae", "jlens") for v in ("trained", "control")}

def pearson(a, b):
    a = a - a.mean(); b = b - b.mean()
    return float(a @ b / (np.sqrt(a @ a) * np.sqrt(b @ b) + 1e-12))

r_trained = pearson(conc[("sae","trained")], conc[("jlens","trained")])
r_control = pearson(conc[("sae","control")], conc[("jlens","control")])
print(f"Concentration Gini par position (T={conc[('sae','trained')].size})")
print(f"  SAE   trained : mean={conc[('sae','trained')].mean():.4f}  std={conc[('sae','trained')].std():.4f}")
print(f"  JLENS trained : mean={conc[('jlens','trained')].mean():.4f}  std={conc[('jlens','trained')].std():.4f}")
print(f"  Pearson(SAE, J-Lens) TRAINED = {r_trained:+.4f}")
print(f"  Pearson(SAE, J-Lens) CONTROL = {r_control:+.4f}")

# 1. Degradation individuelle
def topk_stats(lens, variant):
    vals = np.concatenate([traces[(lens,variant)]["prompts"][(s,i)]["vals"].astype(np.float64).ravel()
                           for s in SETS for i in range(4)])
    top1 = np.concatenate([traces[(lens,variant)]["prompts"][(s,i)]["vals"].astype(np.float64)[:,0]
                           for s in SETS for i in range(4)])
    return vals.mean(), top1.mean(), top1.max()

print(f"{'lentille':8s} {'variant':8s} {'mean(val)':>10s} {'mean(top1)':>11s} {'max(top1)':>10s}")
for lens in ("sae", "jlens"):
    for v in ("trained", "control"):
        mv, mt1, xt1 = topk_stats(lens, v)
        print(f"{lens:8s} {v:8s} {mv:>10.3f} {mt1:>11.3f} {xt1:>10.3f}")

# 2. Degradation croisee (correlation de concentration)
print()
print(f"Correlation concentration SAE<->J-Lens : TRAINED = {r_trained:+.4f}  CONTROL = {r_control:+.4f}")
delta = r_trained - r_control
print(f"Delta (trained - control) = {delta:+.4f}")
if delta > 0:
    print("  -> Le signal croise se degrade sur le controle : l'ablation valide la correspondance.")
else:
    print("  -> Le signal croise NE se degrade pas sur le controle : diverge de robustesse a interpreter.")

## 1. L'animat — un corps, un modèle $\hat p$, une valence $\pi$, une faim

`PregnanceAnimat` réutilise les fondations de ICT-12b sans les modifier :

* un **modèle prédictif** $\hat p$ (`predict_source` de ICT-12 : extrapolation EMA-vitesse de la position future des objets) ;
* une **valence apprise** $\pi$ (la classe `LearnedValence` de ICT-12b : Rescorla-Wagner, neutre à l'init) ;
* un **drive interne** `hunger` (croît avec le temps, tombe à la capture d'une source) ;
* une **politique** $a_t = f(\text{salience}, \text{hunger})$ où la salience apparente d'un objet est $\pi_i + \text{intrinsic}_i$ (valence apprise + valence innée de source).

Le couplage incarné : la valence décide **SI** on poursuit ; la crédibilité de $\hat p$ décide **COMMENT** (interception anticipée si $\hat p$ est fiable, poursuite réactive sinon). Sur un régime **erratique**, $\hat p$ est peu fiable — l'animat poursuit réactivement, là où la cible *est*. C'est le germe de la dissociation.

## Conclusion

**Ce notebook incarne le maillon « animat inhibé » de l'échelle Laborit** (animat simple → *animat inhibé* → agent augmenté → agent créateur → collectif) comme un substrat expérimental falsifiable, et en livre quatre verdicts contrôlés :

1. **Détection** — l'animat estime $\alpha$ depuis ses transitions (corrigé de la ligne de chance) ;
2. **Rigidification** — sous inhibition, sa politique se replie et la diversité d'action s'effondre ;
3. **Perte d'efficacité** — il ne peut plus atteindre ni maintenir un but, quand bien même il le cherche ;
4. **Pont $I(R)$** — l'action ne module plus la dette d'irréversibilité subie, preuve qu'elle a cessé d'être opérante.

**Robustesse** : les trois bancs stochastiques tiennent leurs verdicts sur cinq seeds externes $[0, 1, 7, 42, 99]$ — aucune bascule, dispersion faible devant les marges (section 6, tableau par métrique) ; le pont $I(R)$ est déterministe, robuste par construction.

**Portée honnête** : substrat 1-torus minimal (anneau à 9 états) — l'objet est la *mécanique* de l'inhibition de l'action (détection → rigidification → perte de prise sur $I(R)$), transposable à des animats richer. La rencontre avec la strate 7 (inhibition de l'**innovation**, [ICT-30](ICT-30-InhibitedInvention-Python.ipynb), #7746) est une issue ultérieure ; ce notebook reste au niveau **animat individuel**.

*Module* : [`ict.inhibited_action`](ict/inhibited_action.py) (PR [#8825](https://github.com/jsboige/CoursIA/pull/8825)). *Parallèle* : [C1 — ICT-12c](ICT-12c-PregnanceAnimat-Python.ipynb) (#7740). *Références* : Laborit 1976 (*L'Éloge de la fuite*) ; spec #7741 (conversation de conception tours 756-761, 2026-07-20) ; pont $I(R)$ via `ict.reversibility_budget` (ICT-18).

def simulate_sznajd(n_agents=50, n_steps=1500, seed=0):
    rng = np.random.default_rng(seed)
    opinions = rng.choice([-1, 1], size=n_agents)
    states = []
    for _ in range(n_steps):
        states.append(int(np.sum(opinions > 0)))
        i, j = rng.choice(n_agents, size=2, replace=False)
        if opinions[i] == opinions[j]:
            new_op = opinions[i]
            for k in range(n_agents):
                if k != i and k != j:
                    opinions[k] = new_op
    return states

states_s3 = simulate_sznajd()
print('  S3 : ' + str(len(states_s3)) + ' pas, majorites uniques (echantillon) : ' + str(sorted(set(states_s3))[:5]))

_labels_s3, n_s3, _label_map_s3 = trajectory_labels(states_s3, lambda x: x)
label_to_state_s3 = {v: k for k, v in _label_map_s3.items()}
f_native_s3 = lambda natif: int(natif >= 25)

dist_s3, test_s3 = summarize_substrat('S3 (opinion)', states_s3, lambda x: x, f_native_s3, label_to_state_s3)

# Imports et setup
import sys
